review.sql:
MERGE INTO D d USING S s ON(d.id=s.id)
WHEN MATCHED THEN UPDATE SET d.v=s.v
WHEN NOT MATCHED THEN INSERT(id,v) VALUES(s.id,s.v);

SELECT CASE WHEN score>=80 THEN 'B'
 WHEN score>=90 THEN 'A' ELSE 'C' END AS grade
FROM T;

mocks.sql:
MERGE INTO D d USING S s ON(d.id=s.id)
WHEN MATCHED THEN UPDATE SET d.v=d.v-s.delta
DELETE WHERE d.v=0;

MERGE INTO D d USING S s ON(d.id=s.id)
WHEN MATCHED THEN UPDATE SET d.v=s.v WHERE s.v>0
WHEN NOT MATCHED THEN INSERT(id,v) VALUES(s.id,s.v);

SELECT a.id FROM A a LEFT JOIN B b
 ON a.k=b.k AND b.flag='Y';
-- Q
SELECT a.id FROM A a LEFT JOIN B b ON a.k=b.k
 WHERE b.flag='Y';

SELECT id FROM T
WHERE (v>=0 AND code<>'X') OR v IS NULL
ORDER BY id;

SELECT id FROM T
WHERE (qty>0 AND status='O') OR urgent='Y'
ORDER BY id;
